#include <bits/stdc++.h>
using namespace std;
using ll = long long;
ll comb[62][62], costA[32][32], costB[32][32];
int R, C, L;
char dir[110];
ll total;
ll diff;
ll res;
vector<pair<ll, ll>> store1[32][2], store2[32][2];
ll cnt[32][32];

void store_fwd(int x, int y, ll gain, ll c1, ll c2, bool flg) {
    if (x + y == L) {
        store1[x][flg].push_back({gain, c1});
        if (c2) store2[x][flg].push_back({gain, c2});
        return;
    }
    if (x + 1 <= L)
        store_fwd(x+1, y, gain + (!flg ? costA[x+1][y] : 0), c1, (dir[x+y] != 'B' ? c2 : 0), flg);
    if (y + 1 <= L)
        store_fwd(x, y+1, gain + (flg ? costB[x][y+1] : 0), c1, (dir[x+y] != 'A' ? c2 : 0), flg);
}

void forward_search(int x, int y, ll sum, bool flg) {
    if (x + y == L) {
        if (store1[x][flg].empty()) return;
        auto lb = lower_bound(store1[x][flg].begin(), store1[x][flg].end(), make_pair((total+1)/2 - sum, 0LL));
        for (auto it = lb; it != store1[x][flg].end() && it - lb < 2; ++it) {
            if (it->second <= 0) continue;
            ll cur = llabs((it->first + sum) * 2 - total);
            if (cur < diff) diff = cur;
        }
        if (lb != store1[x][flg].begin()) {
            auto it = prev(lb);
            if (it->second > 0) {
                ll cur = llabs((it->first + sum) * 2 - total);
                if (cur < diff) diff = cur;
            }
        }
        return;
    }
    if (x > 0) forward_search(x-1, y, sum + (!flg ? costA[x][y] : 0), flg);
    if (y > 0) forward_search(x, y-1, sum + (flg ? costB[x][y] : 0), flg);
}

void backward_search(int x, int y, ll sum, bool flg) {
    if (x + y == L) {
        auto lb = lower_bound(store2[x][flg].begin(), store2[x][flg].end(), make_pair((total+1)/2 - sum, 0LL));
        for (auto it = lb; it != store2[x][flg].end() && it - lb < 2; ++it) {
            if (it->second <= 0) continue;
            ll cur = llabs((it->first + sum) * 2 - total);
            if (cur == diff) res += it->second;
        }
        if (lb != store2[x][flg].begin()) {
            auto it = prev(lb);
            if (it->second > 0) {
                ll cur = llabs((it->first + sum) * 2 - total);
                if (cur == diff) res += it->second;
            }
        }
        return;
    }
    if (x > 0 && dir[x+y-1] != 'B') backward_search(x-1, y, sum + (!flg ? costA[x][y] : 0), flg);
    if (y > 0 && dir[x+y-1] != 'A') backward_search(x, y-1, sum + (flg ? costB[x][y] : 0), flg);
}

void merge(vector<pair<ll,ll>>& v) {
    if (v.empty()) return;
    sort(v.begin(), v.end());
    vector<pair<ll,ll>> tmp;
    ll last = v[0].first, accum = 0;
    for (auto p : v) {
        if (p.first == last) accum += p.second;
        else {
            tmp.emplace_back(last, accum);
            last = p.first;
            accum = p.second;
        }
    }
    tmp.emplace_back(last, accum);
    v = tmp;
}

int main() {
    scanf("%d %d", &R, &C);
    scanf("%s", dir);
    for (int i = 0; i <= 60; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; ++j) comb[i][j] = comb[i-1][j-1] + comb[i-1][j];
    }
    L = R + C;
    total = comb[L*2][R*2];
    for (int i = 0; i <= L; ++i) {
        for (int j = 0; j <= L; ++j) {
            if (i) costA[i][j] = comb[i-1][R-1] * (comb[L*2-i][R] - comb[j][R]);
            if (j) costB[i][j] = comb[j-1][R-1] * (comb[L*2-j][R] - comb[i][R]);
        }
    }
    cnt[0][0] = 1;
    for (int i = 0; i <= L; ++i) {
        for (int j = 0; j <= L; ++j) {
            if (i < L && dir[i+j] != 'B') cnt[i+1][j] += cnt[i][j];
            if (j < L && dir[i+j] != 'A') cnt[i][j+1] += cnt[i][j];
        }
    }
    for (int i = R; i <= L; ++i) {
        if (dir[i+R-1] != 'B') store_fwd(R, i, costA[R][i], comb[i+R-1][R-1], cnt[R-1][i], 0);
        if (dir[i+R-1] != 'A') store_fwd(i, R, costB[i][R], comb[i+R-1][R-1], cnt[i][R-1], 1);
    }
    for (int i = R; i <= L; ++i) {
        for (int k = 0; k < 2; ++k) {
            merge(store1[i][k]);
            merge(store2[i][k]);
        }
    }
    diff = total + 1;
    forward_search(L, L, 0, 0);
    forward_search(L, L, 0, 1);
    backward_search(L, L, 0, 0);
    backward_search(L, L, 0, 1);
    printf("%lld\n", res);
}
